<template>
  <div class="wrap">
    <div class="con-bottom top" v-if="progress_ != 11">
      <div class="status-top">
        <button type="button" class="btn btn-close" @click="btnExit"></button>
      </div>
      <div class="status-wrap">
        <div class="status-bar">
          <div class="fill" :style="{ width: progress_ * 10 + '%' }">
            <span class="percent">{{ progress_ * 10 }}%</span>
          </div>
        </div>
      </div>
    </div>
    <div
      class="content bg top-exist"
      v-if="progress_ != 11"
      v-bind:class="{ 'keypad-exist': keyState[progress_] }"
    >
      <ul class="chat-list" ref="msg">
        <li class="chat-list--item left" v-if="progress_ >= 3">
          <div class="chat-wrap">
            <div class="top">
              <strong>주택 보유를 하고 있나요?</strong>
            </div>
            <div class="bottom" v-if="progress_ === 3">
              <div class="check-list">
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="capital"
                    value="1주택 이상 보유"
                    v-model="userData.HouseOwnership"
                    @click="btnSend('1주택 이상 보유')"
                  />
                  <span class="text">1주택 이상 보유</span>
                </label>
                <label class="check-wrap">
                  <input
                    type="radio"
                    name="capital"
                    value="무주택"
                    v-model="userData.HouseOwnership"
                    @click="btnSend('무주택')"
                  />
                  <span class="text">무주택</span>
                </label>
              </div>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="userData.HouseOwnership != '' && progress_ >= 3"
        >
          <div class="chat-wrap">
            <div class="top">{{ userData.HouseOwnership }}</div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 4">
          <div class="chat-wrap">
            <div class="top">
              <strong>가용 가능한 금액을 입력해주세요.</strong>
            </div>
            <div class="bottom" v-if="progress_ == 4">
              <div class="input">{{ userData.AvailableAmount | comma }}</div>
              <span class="guide">{{ assets_ }}</span>
            </div>
            <div class="bottom" v-else>
              <button type="button" class="btn" @click="btnGoToback(4)">
                가용 금액 다시 입력
                <img src="../../../public/images/icon/arrow.svg" />
              </button>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="assets_ != '' && progress_ >= 5"
        >
          <div class="chat-wrap">
            <div class="top">{{ assets_ }}원</div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 5">
          <div class="chat-wrap">
            <div class="top">
              <strong>원하는 대출 비율을 선택하세요.</strong>
            </div>

            <div class="bottom" v-if="progress_ == 5">
              <div class="range-wrap">
                <!-- 마크 (0102추가) -->
                <span class="mark mark-1"></span>
                <span class="mark mark-2"></span>
                <span class="mark mark-3"></span>
                <span class="mark mark-4"></span>
                <span class="mark mark-5"></span>
                <span class="mark mark-6"></span>
                <strong
                  ><span class="num">{{ userData.LoanRate }}</span
                  >%</strong
                >
                <input
                  type="range"
                  min="0"
                  max="100"
                  value="50"
                  class="styled-slider slider-progress"
                  step="5"
                  :style="{
                    '--min': 0,
                    '--max': 100,
                    '--value': userData.LoanRate,
                  }"
                  v-model="userData.LoanRate"
                />
              </div>
              <button
                type="button"
                class="btn btn-full btn-gradient"
                @click="btnSend(null)"
              >
                입력
              </button>
            </div>
            <div class="bottom" v-else>
              <button type="button" class="btn" @click="btnGoToback(5)">
                대출 비율 다시 입력
                <img src="../../../public/images/icon/arrow.svg" />
              </button>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="assets_ != '' && progress_ >= 6"
        >
          <div class="chat-wrap">
            <div class="top">{{ userData.LoanRate }}%</div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 6">
          <div class="chat-wrap">
            <div class="top">
              <strong>신용 점수를 선택하세요.</strong>
            </div>
            <div class="bottom" v-if="progress_ === 6">
              <div class="check-list">
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="score_1"
                    value="700점 이상"
                    v-model="userData.CreditScore"
                    @click="btnSend('700점 이상')"
                  />
                  <span class="text">700점 이상</span>
                </label>
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="score_2"
                    value="700점 미만"
                    v-model="userData.CreditScore"
                    @click="btnSend('700점 미만')"
                  />
                  <span class="text">700점 미만</span>
                </label>
              </div>
            </div>
            <div class="bottom" v-else>
              <button type="button" class="btn" @click="btnGoToback(6)">
                신용 점수 다시 입력
                <img src="../../../public/images/icon/arrow.svg" />
              </button>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="userData.HouseOwnership != '' && progress_ >= 7"
        >
          <div class="chat-wrap">
            <div class="top">{{ userData.CreditScore }}</div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 7">
          <div class="chat-wrap">
            <div class="top">
              <strong>원하는 거래 유형을 선택하세요.</strong>
            </div>
            <div class="bottom" v-if="progress_ === 7">
              <div class="check-list">
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="ttype_1"
                    value="매매"
                    v-model="userData.TransactionType"
                    @click="btnSend('매매')"
                  />
                  <span class="text">매매</span>
                </label>
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="ttype_2"
                    value="전세"
                    v-model="userData.TransactionType"
                    @click="btnSend('전세')"
                  />
                  <span class="text">전세</span>
                </label>
              </div>
            </div>
            <div class="bottom" v-else>
              <button type="button" class="btn" @click="btnGoToback(7)">
                거래 유형 다시 입력
                <img src="../../../public/images/icon/arrow.svg" />
              </button>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="userData.HouseOwnership != '' && progress_ >= 8"
        >
          <div class="chat-wrap">
            <div class="top">{{ userData.TransactionType }}</div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 8">
          <div class="chat-wrap">
            <div class="top">
              <strong>원하는 매물 유형을 선택하세요.</strong>
            </div>
            <div class="bottom" v-if="progress_ === 8">
              <div class="check-list">
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="sale_1"
                    value="아파트"
                    v-model="userData.PropertyType"
                    @click="btnSend('아파트')"
                  />
                  <span class="text">아파트</span>
                </label>
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="sale_2"
                    value="오피스텔"
                    v-model="userData.PropertyType"
                    @click="btnSend('오피스텔')"
                  />
                  <span class="text">오피스텔</span>
                </label>
                <label class="check-wrap">
                  <input
                    type="radio"
                    id="sale_3"
                    value="기타"
                    v-model="userData.PropertyType"
                    @click="btnSend('기타')"
                  />
                  <span class="text">기타</span>
                </label>
              </div>
            </div>
            <div class="bottom" v-else>
              <button type="button" class="btn" @click="btnGoToback(8)">
                매물 유형 다시 입력
                <img src="../../../public/images/icon/arrow.svg" />
              </button>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="userData.HouseOwnership != '' && progress_ >= 9"
        >
          <div class="chat-wrap">
            <div class="top">{{ userData.PropertyType }}</div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 9">
          <div class="chat-wrap">
            <div class="top">
              <strong>원하는 지역을 선택하세요.</strong>
            </div>
            <div class="bottom" v-if="progress_ === 9">
              <VuePicker
                v-model="userData.City"
                key="City_pick"
                class="m-b--10"
              >
                <vue-picker-option
                  @click="btnSend('-1')"
                  value="-1"
                  key="city_"
                >
                  선택
                </vue-picker-option>
                <template v-for="c in cities">
                  <div @click="getDvsns(c.Id)" :key="'city_' + c.Id">
                    <vue-picker-option :value="c.Id + ''">
                      {{ c.Name }}
                    </vue-picker-option>
                  </div>
                </template>
              </VuePicker>
              <VuePicker v-model="userData.County" key="County_pick">
                <vue-picker-option value="-1" key="dvsns_">
                  선택
                </vue-picker-option>
                <template v-for="c in dvsns">
                  <div
                    :key="'dvsns_' + c.Id"
                    v-if="userData.City != '-1'"
                    @click="btnSend(null)"
                  >
                    <vue-picker-option :value="c.Id + ''">
                      {{ c.Name }}
                    </vue-picker-option>
                  </div>
                </template>
              </VuePicker>
            </div>
            <div class="bottom" v-else>
              <button type="button" class="btn" @click="btnGoToback(9)">
                희망 지역 다시 입력
                <img src="../../../public/images/icon/arrow.svg" />
              </button>
            </div>
          </div>
        </li>
        <li
          class="chat-list--item right"
          v-if="userData.HouseOwnership != '' && progress_ >= 10"
        >
          <div class="chat-wrap">
            <div class="top">
              {{ getCityName(userData.City) }}/
              {{ getDvsnName(userData.County) }}
            </div>
          </div>
        </li>

        <li class="chat-list--item left" v-if="progress_ >= 10">
          <div class="chat-wrap">
            <div class="top">
              <ul class="input-list">
                <li class="input-list--item">
                  <label>가용 금액</label>
                  <span>{{ assets_ }}원</span>
                </li>
                <li class="input-list--item">
                  <label>대출 비율</label>
                  <span>{{ userData.LoanRate }}%</span>
                </li>
                <li class="input-list--item">
                  <label>신용 점수</label>
                  <span>{{ userData.CreditScore }}</span>
                </li>
                <li class="input-list--item">
                  <label>거래 유형</label>
                  <span>{{ userData.TransactionType }}</span>
                </li>
                <li class="input-list--item">
                  <label>매물 유형</label>
                  <span>{{ userData.PropertyType }}</span>
                </li>
                <li class="input-list--item">
                  <label>관심 지역</label>
                  <span>
                    {{ getCityName(userData.City) }}
                    ({{ getDvsnName(userData.County) }})
                  </span>
                </li>
              </ul>
              <button class="btn btn-full btn-gradient" @click="saveMyHome">
                입력
              </button>
            </div>
          </div>
        </li>
      </ul>
    </div>

    <div class="key-pad" v-if="keyState[progress_]">
      <ul class="key-list">
        <li class="key-list--item" @click="iNumber('1')">1</li>
        <li class="key-list--item" @click="iNumber('2')">2</li>
        <li class="key-list--item" @click="iNumber('3')">3</li>
        <li class="key-list--item" @click="iNumber('4')">4</li>
        <li class="key-list--item" @click="iNumber('5')">5</li>
        <li class="key-list--item" @click="iNumber('6')">6</li>
        <li class="key-list--item" @click="iNumber('7')">7</li>
        <li class="key-list--item" @click="iNumber('8')">8</li>
        <li class="key-list--item" @click="iNumber('9')">9</li>

        <li
          v-if="progress_ == 1"
          class="key-list--item"
          @click="iNumber('010')"
        >
          010
        </li>
        <li v-else class="key-list--item"></li>

        <li class="key-list--item" @click="iNumber('0')">0</li>
        <li class="key-list--item" @click="iNumber('back')">
          <img src="../../../public/images/icon/delete.svg" />
        </li>
      </ul>
      <button
        type="button"
        class="btn btn-full btn-gradient"
        @click="btnSend(null)"
      >
        입력
      </button>
    </div>
  </div>
</template>

<script>
export default {
  name: "SetMyHome",
  props: {
    // rProgress: {
    //   type: Number,
    //   default: 1,
    // },
  },
  components: {},
  mounted() {
    setInterval(() => this.count++, 1000);
    this.mapOptions.zoom = this.zoomLevel;
    this.getCities();
    this.init();
  },
  updated() {
    // console.log(this.keyState[this.progress_]);
    // console.log(this.userData.LoanRate);
  },
  filters: {
    comma(val) {
      return String(val).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    },
  },
  watch: {
    progress_() {
      // 화면에 추가된 후 동작하도록
      this.$nextTick(() => {
        let messages = this.$refs.msg;
        messages.scrollTo({
          top: messages.scrollHeight,
          behavior: "smooth",
        });
      });
    },
  },
  data() {
    return {
      pickKey: 0,
      keyState: [
        true,
        true,
        true,
        false,
        true,
        false,
        false,
        false,
        false,
        false,
        false,
      ],
      rBtnState: false,

      zoomLevel: 10,
      width: window.innerWidth,
      height: window.innerHeight - 100,
      info: false,
      marker: null,
      count: 1,
      map: null,
      isCTT: false,
      mapOptions: {
        lat: 37,
        lng: 127,
        zoom: 10,
        zoomControl: false,
        zoomControlOptions: { position: "TOP_RIGHT" },
        mapTypeControl: false,
      },
      initLayers: [
        "BACKGROUND",
        "BACKGROUND_DETAIL",
        "POI_KOREAN",
        "TRANSIT",
        "ENGLISH",
        "CHINESE",
        "JAPANESE",
      ],

      progress_: 3,
      phoneNumber_: "",
      VerifyKey: "001234",
      assets_: "",
      cities: [],
      dvsns: [],
      cityData: {
        AAA: ["A1", "A2", "A3"],
        BBB: ["B1", "B2", "B3"],
        CCC: ["C1", "C2", "C3"],
      },
      userData: {
        Contact: "", //휴대폰번호
        VerifyKey: "", //인증번호
        HouseOwnership: "", //주택 보유 여부 string
        AvailableAmount: "", //가용금액 string
        LoanRate: 50, //대출 비율
        CreditScore: "", //신용점수
        TransactionType: "", //거래유형
        PropertyType: "", //매매유형
        City: "-1", //시/도
        County: "-1", //구/군
      },
    };
  },
  methods: {
    init() {
      // this.$store.commit("init");
      // this.getUserData();
    },
    saveMyHome() {
      this.$apiPOST("/myhome/additional", {
        HouseOwnership: this.userData.HouseOwnership,
        AvailableAmount: Number(this.userData.AvailableAmount),
        LoanRate: Number(this.userData.LoanRate),
        CreditScore: this.userData.CreditScore,
        TransactionType: this.userData.TransactionType,
        PropertyType: this.userData.PropertyType,
        CityId: Number(this.userData.City),
        CountyId: Number(this.userData.County),
      }).then((re) => {
        if (re.data.code === 200) {
          this.$router.go(-1);
        } else {
          console.log("에러 ", re.code + " ");
        }
      });
    },
    getCityName(id) {
      for (let i = 0; i < this.cities.length; i++) {
        if (Number(this.cities[i].Id) == Number(id)) {
          return this.cities[i].Name;
        }
      }
      return "none";
    },
    getDvsnName(id) {
      for (let i = 0; i < this.dvsns.length; i++) {
        if (Number(this.dvsns[i].Id) == Number(id)) {
          return this.dvsns[i].Name;
        }
      }
      return "none";
    },
    getCities() {
      this.$apiGET("/cities").then(({ data }) => {
        this.cities = data.d;
      });
    },
    _getDvsns(id, countyId) {
      this.$apiGET("/dvsns?CityId=" + id).then(({ data }) => {
        this.dvsns = data.d;
        this.userData.County = countyId;
      });
    },
    getDvsns(id) {
      this.$apiGET("/dvsns?CityId=" + id).then(({ data }) => {
        this.dvsns = data.d;
        this.userData.County = "-1";
      });
    },
    getUserData() {
      this.$apiGET("/myhome/home").then(({ data }) => {
        if (data.code === 200) {
          if (data.d.Step != null) {
            this.progress_ = data.d.Step + 1;
          }

          if (data.d.AvailableAmount != null) {
            this.userData.AvailableAmount = String(data.d.AvailableAmount);
            this.assets_ = this.numberToKorean(this.userData.AvailableAmount);
          }

          if (data.d.CityId != null) {
            this.userData.City = String(data.d.CityId);
          }

          if (data.d.CountyId != null) {
            this._getDvsns(this.userData.City, String(data.d.CountyId));
          }

          if (data.d.Contact != null) {
            this.userData.Contact = data.d.Contact;
          }

          if (data.d.CreditScore != null) {
            this.userData.CreditScore = data.d.CreditScore;
          }

          if (data.d.HouseOwnership != null) {
            this.userData.HouseOwnership = data.d.HouseOwnership;
          }

          if (data.d.LoanRate != null) {
            this.userData.LoanRate = data.d.LoanRate;
          }

          if (data.d.PropertyType != null) {
            this.userData.PropertyType = data.d.PropertyType;
          }

          if (data.d.TransactionType != null) {
            this.userData.TransactionType = data.d.TransactionType;
          }
        }
      });
    },
    iNumber(num) {
      if (this.progress_ === 1) {
        if (num === "back") {
          this.phoneNumber_ = this.phoneNumber_.slice(0, -1);
          this.userData.Contact = this.getMask(this.phoneNumber_);
        } else if (this.phoneNumber_.length < 11) {
          if (num === "010") {
            if (this.phoneNumber_.length === 0) {
              this.phoneNumber_ += num;
              this.userData.Contact = this.getMask(this.phoneNumber_);
            }
          } else {
            this.phoneNumber_ += num;
            this.userData.Contact = this.getMask(this.phoneNumber_);
          }
        }
      } else if (this.progress_ === 2) {
        if (num === "back") {
          this.userData.VerifyKey = this.userData.VerifyKey.slice(0, -1);
        } else if (this.userData.VerifyKey.length < 11) {
          if (num === "010") {
            if (this.userData.VerifyKey.length === 0) {
              this.userData.VerifyKey += num;
            }
          } else {
            this.userData.VerifyKey += num;
          }
        }
      } else if (this.progress_ === 4) {
        if (num === "back") {
          this.userData.AvailableAmount = this.userData.AvailableAmount.slice(
            0,
            -1
          );
          this.assets_ = this.numberToKorean(this.userData.AvailableAmount);
        } else if (this.userData.AvailableAmount.length < 11) {
          if (num === "010") {
            if (this.userData.AvailableAmount.length === 0) {
              this.userData.AvailableAmount += num;
              this.assets_ = this.numberToKorean(this.userData.AvailableAmount);
            }
          } else {
            this.userData.AvailableAmount += num;
            this.assets_ = this.numberToKorean(this.userData.AvailableAmount);
          }
        }
        if (this.assets_.charAt(this.assets_.length - 1) === " ") {
          this.assets_ = this.assets_.slice(0, -1);
        }
      }
    },
    btnSend(param) {
      if (this.progress_ === 1) {
        //전화번호
        this.progress_++;
      } else if (this.progress_ === 2) {
        //인증번호
        this.progress_++;
      } else if (this.progress_ === 3) {
        //주택 보유 여부
        this.userData.HouseOwnership = param;
        this.progress_++;
      } else if (this.progress_ === 4) {
        //가용가능한 금액
        this.progress_++;
      } else if (this.progress_ === 5) {
        //대출비율
        this.progress_++;
      } else if (this.progress_ === 6) {
        //신용점수
        this.userData.CreditScore = param;
        this.progress_++;
      } else if (this.progress_ === 7) {
        //거래유형
        this.userData.TransactionType = param;
        this.progress_++;
      } else if (this.progress_ === 8) {
        //매물유형
        this.userData.PropertyType = param;
        this.progress_++;
      } else if (this.progress_ === 9) {
        //지역
        this.progress_++;
      } else if (this.progress_ === 10) {
        this.keyState = false;
        this.progress_++;
      }
    },

    btnGoToback(prg) {
      this.progress_ = prg;
    },
    getMask(phoneNumber) {
      if (!phoneNumber) return phoneNumber;
      phoneNumber = phoneNumber.replace(/[^0-9]/g, "");

      let res = "";
      if (phoneNumber.length < 3) {
        res = phoneNumber;
      } else {
        if (phoneNumber.substr(0, 2) == "02") {
          if (phoneNumber.length <= 5) {
            //02-123-5678
            res = phoneNumber.substr(0, 2) + "-" + phoneNumber.substr(2, 3);
          } else if (phoneNumber.length > 5 && phoneNumber.length <= 9) {
            //02-123-5678
            res =
              phoneNumber.substr(0, 2) +
              "-" +
              phoneNumber.substr(2, 3) +
              "-" +
              phoneNumber.substr(5);
          } else if (phoneNumber.length > 9) {
            //02-1234-5678
            res =
              phoneNumber.substr(0, 2) +
              "-" +
              phoneNumber.substr(2, 4) +
              "-" +
              phoneNumber.substr(6);
          }
        } else {
          if (phoneNumber.length < 8) {
            res = phoneNumber;
          } else if (phoneNumber.length == 8) {
            res = phoneNumber.substr(0, 4) + "-" + phoneNumber.substr(4);
          } else if (phoneNumber.length == 9) {
            res =
              phoneNumber.substr(0, 3) +
              "-" +
              phoneNumber.substr(3, 3) +
              "-" +
              phoneNumber.substr(6);
          } else if (phoneNumber.length == 10) {
            res =
              phoneNumber.substr(0, 3) +
              "-" +
              phoneNumber.substr(3, 3) +
              "-" +
              phoneNumber.substr(6);
          } else if (phoneNumber.length > 10) {
            //010-1234-5678
            res =
              phoneNumber.substr(0, 3) +
              "-" +
              phoneNumber.substr(3, 4) +
              "-" +
              phoneNumber.substr(7);
          }
        }
      }

      return res;
    },
    numberToKorean(number) {
      var inputNumber = number < 0 ? false : number;
      var unitWords = ["", "만 ", "억 ", "조 ", "경 "];
      var splitUnit = 10000;
      var splitCount = unitWords.length;
      var resultArray = [];
      var resultString = "";

      for (var i = 0; i < splitCount; i++) {
        var unitResult =
          (inputNumber % Math.pow(splitUnit, i + 1)) / Math.pow(splitUnit, i);
        unitResult = Math.floor(unitResult);
        if (unitResult > 0) {
          if (i == 0) {
            resultArray[i] = 0;
          } else {
            resultArray[i] = unitResult;
          }
        }
      }

      for (let i = 0; i < resultArray.length; i++) {
        if (!resultArray[i]) continue;
        resultString = String(resultArray[i]) + unitWords[i] + resultString;
      }

      return resultString;
    },
    btnExit() {
      this.$router.go(-1);
      // this.$emit("setState", false, this.userData, this.progress_);
    },
  },
};
</script>
